<script setup lang="ts">import {ref,onMounted,watch} from 'vue';import {onShow} from '@dcloudio/uni-app';import {api} from '../../api';import UnlockDialog from '../../components/UnlockDialog.vue';import {useSessionStore} from '../../store/session';import {locale,t,syncTabBarLocale} from '../../locales';import '../../styles/app.scss';const items=ref<any[]>([]);const active=ref('全部');const loading=ref(true);const error=ref(false);const showUnlock=ref(false);const store=useSessionStore();const filters=['全部','做多','做空','自选'];function openLogin(){uni.setStorageSync('cf_after_login','points');uni.reLaunch({url:'/pages/index/index?auth=login'})}async function load(){if(!store.token){openLogin();return}loading.value=true;error.value=false;try{items.value=active.value==='自选'?await api.favorites('points'):await api.points(active.value==='做多'||active.value==='做空'?active.value:undefined)}catch{error.value=true}finally{loading.value=false}}onMounted(load);onShow(() => { syncTabBarLocale(); store.syncTabBarTheme() });watch(locale,load);function choose(x:string){active.value=x;load()}function detail(id:string){uni.navigateTo({url:'/pages/detail/point?id='+id})}async function unlocked(){store.unlocked=true;uni.setStorageSync('cf_unlocked',true);showUnlock.value=false;await load();uni.showToast({title:t('点位已解锁'),icon:'none'})}</script>
<template><view class="points-page"><view class="points-header"><view><text class="points-title">{{t('交易点位')}}</text><text class="live-label">{{t('实时策略')}}</text></view><button v-if="!store.unlocked" class="unlock-link" @click="showUnlock=true"><svg class="unlock-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 1 1 8 0v3"/></svg><text>{{t('全部解锁')}}</text></button><text v-else class="live-label">{{t('已解锁')}}</text></view><view class="point-filters"><text v-for="x in filters" :key="x" class="point-filter" :class="{active:active===x}" @click="choose(x)">{{t(x)}}</text></view><view v-if="loading" class="point-state">{{t('加载中...')}}</view><view v-else-if="error" class="point-state">{{t('加载失败，请重试')}}<button class="outline" @click="load">{{t('重试')}}</button></view><view v-else-if="!items.length" class="point-state">{{t('暂无点位')}}</view><view v-else class="point-results"><view v-for="p in items" :key="p.id" class="point-card" :class="{expired:p.status==='已失效'}" @click="p.locked&&!store.unlocked?showUnlock=true:detail(p.id)"><view class="point-card-header"><view class="coin-title"><text class="coin-icon" :class="p.coin.startsWith('BTC')?'btc':p.coin.startsWith('ETH')?'eth':'sol'">{{p.coin.startsWith('BTC')?'₿':p.coin.startsWith('ETH')?'◆':'◎'}}</text><text>{{p.coin}}</text><text class="direction" :class="p.dir==='做多'?'up':'down'">{{t(p.dir)}}</text></view><text class="status" :class="p.status==='已失效'?'inactive':''">{{t(p.status)}}</text></view><view v-if="p.locked&&!store.unlocked" class="locked-row">♧ {{t('点位详情已锁定，点击解锁')}}</view><view v-else class="point-values"><view><text>{{t('入场区间')}}</text><text>{{p.range}}</text></view><view><text>{{t('止盈')}}</text><text>{{p.tp}}</text></view><view><text>{{t('止损')}}</text><text class="down">{{p.sl}}</text></view></view><view class="point-card-foot"><text>{{t('发布时间')}} {{p.published || '2026-07-13 20:30'}}</text><text>{{t('有效期')}} {{p.validity || '24H'}}</text></view></view></view><UnlockDialog :visible="showUnlock" @close="showUnlock=false" @unlocked="unlocked"/></view></template>
<style scoped>.points-page{min-height:100vh;padding:26rpx 26rpx 120rpx;background:#F8FAFC;color:var(--cf-text)}.points-header,.points-header>view{display:flex;align-items:center;justify-content:space-between;gap:10rpx}.points-title{font-size:35rpx;font-weight:800}.live-label{padding:5rpx 10rpx;background:#EFF6FF;color:var(--cf-brand);font-size:21rpx;font-weight:700}.unlock-link{margin:0;padding:10rpx 15rpx;border:1rpx solid #BFDBFE;border-radius:22rpx;background:#EFF6FF;color:var(--cf-brand);font-size:21rpx}.point-filters{display:flex;gap:14rpx;margin:28rpx 0 24rpx}.point-filter{padding:9rpx 20rpx;border:1rpx solid var(--cf-line);border-radius:24rpx;background:#fff;color:var(--cf-muted);font-size:23rpx}.point-filter.active{background:var(--cf-brand);border-color:var(--cf-brand);color:#fff}.point-results{display:flex;flex-direction:column;gap:18rpx}.point-card{padding:20rpx;background:#fff;border:1rpx solid var(--cf-line);border-radius:14rpx}.point-card.expired{opacity:.65}.point-card-header,.coin-title,.point-values>view,.point-card-foot{display:flex;align-items:center;justify-content:space-between}.point-card-header{padding-bottom:12rpx;border-bottom:1rpx solid #F1F5F9}.coin-title{justify-content:flex-start;gap:10rpx;font-size:26rpx;font-weight:800}.coin-icon{display:grid;place-items:center;width:34rpx;height:34rpx;border-radius:50%;color:#fff}.coin-icon.btc{background:#F59E0B}.coin-icon.eth{background:#334155}.coin-icon.sol{background:#7C3AED}.direction{padding:3rpx 8rpx;border-radius:5rpx;background:#ECFDF5;font-size:20rpx}.direction.down{background:#FEF2F2}.status{padding:4rpx 10rpx;border:1rpx solid #A7F3D0;border-radius:6rpx;background:#ECFDF5;color:var(--cf-up);font-size:20rpx}.status.inactive{border-color:var(--cf-line);background:#F1F5F9;color:var(--cf-soft)}.point-values{padding:15rpx 0;font-size:22rpx;color:var(--cf-muted)}.point-values>view{margin:7rpx 0;gap:10rpx}.point-values>view text:last-child{color:var(--cf-text);font-weight:700;text-align:right}.point-values>view text.down:last-child{color:var(--cf-down)}.point-card-foot{padding-top:10rpx;border-top:1rpx solid #F1F5F9;color:var(--cf-soft);font-size:19rpx}.locked-row{padding:34rpx 0;color:var(--cf-muted);font-size:23rpx}.point-state{padding:56rpx;text-align:center;color:var(--cf-muted);font-size:22rpx}.modal-mask{position:fixed;inset:0;z-index:1000;display:flex;align-items:center;justify-content:center;padding:36rpx;background:rgba(15,23,42,.45)}.modal{position:relative;width:100%;padding:28rpx;background:#fff;border-radius:18rpx;text-align:center}.modal-close{position:absolute;top:14rpx;right:20rpx;color:var(--cf-soft);font-size:34rpx}.modal-lock{display:grid;place-items:center;width:58rpx;height:58rpx;margin:10rpx auto;border-radius:50%;background:#EFF6FF;color:var(--cf-brand);font-size:32rpx}.modal-title{margin:18rpx 0 11rpx;font-size:28rpx;font-weight:800}.modal-copy{margin-bottom:24rpx;color:var(--cf-muted);font-size:23rpx;line-height:1.5}.modal .primary{width:100%;padding:16rpx;font-size:24rpx}.modal-secondary{display:block;margin-top:17rpx;color:var(--cf-brand);font-size:21rpx}</style>
<style scoped>.points-page{padding-top:calc(26rpx + var(--cf-safe-top))}.unlock-icon{width:38rpx;height:38rpx;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.unlock-dialog{box-sizing:border-box;max-width:690rpx;padding:44rpx 36rpx 34rpx;border:1rpx solid #E5EDF8;border-radius:32rpx;box-shadow:0 18rpx 42rpx rgba(15,23,42,.14)}.unlock-dialog .modal-close{top:20rpx;right:20rpx;width:56rpx;height:56rpx;font-size:52rpx;line-height:1;color:#94A3B8}.unlock-dialog .modal-lock{display:flex;align-items:center;justify-content:center;width:112rpx;height:112rpx;margin:4rpx auto 24rpx;border-radius:50%;background:#EFF6FF;color:#2563EB;font-size:0}.unlock-dialog .modal-lock svg{width:58rpx;height:58rpx;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.unlock-dialog .modal-title{font-size:34rpx;font-weight:800;color:#0F172A}.unlock-dialog .modal-copy{margin:24rpx 0 30rpx;color:#64748B;font-size:25rpx;line-height:1.55}.unlock-dialog .primary{width:100%;height:82rpx;padding:0;border-radius:16rpx;background:#2563EB;color:#fff;font-size:27rpx;font-weight:700}.unlock-dialog .modal-secondary{display:block;margin-top:22rpx;color:#2563EB;font-size:23rpx;text-align:center}</style>
